<template><div class="container-page py-10"><div class="flex items-center justify-between"><div><p class="text-sm text-primary-700">Admin</p><h1 class="text-3xl">Properties</h1></div><NuxtLink to="/admin/properties/new" class="btn-primary">Add Property</NuxtLink></div><p class="mt-3 text-neutral-600">Manage published, draft and inactive property records.</p><p v-if="pending" class="mt-8">Loading properties…</p><p v-else-if="loadError" class="mt-8 rounded-lg bg-error-50 p-4 text-error-800">{{loadError.message}}</p><div v-else class="card mt-8 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-neutral-100"><tr><th class="p-4">Property</th><th class="p-4">Location</th><th class="p-4">From</th><th class="p-4">Visibility</th><th class="p-4"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="property in properties" :key="property.id" class="border-t"><td class="p-4 font-semibold">{{property.name}}</td><td class="p-4">{{property.location_name}}</td><td class="p-4">{{money(property.price_from)}}</td><td class="p-4"><span :class="property.published&&property.is_active?'badge-success':'badge-warning'">{{property.published&&property.is_active?'Published':property.published?'Inactive':'Draft'}}</span></td><td class="p-4 text-right"><NuxtLink :to="`/admin/properties/${property.id}`" class="font-semibold text-primary-700">Edit</NuxtLink></td></tr><tr v-if="!properties?.length"><td colspan="5" class="p-6 text-center text-neutral-500">No properties found.</td></tr></tbody></table></div></div></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin-auth'});const db=useSupabase();const{data:properties,pending,error:loadError}=useAsyncData('admin-properties',async()=>{const{data,error}=await db.from('properties').select('*').order('sort_order').order('created_at');if(error)throw error;return data||[]});const money=(v:number|null)=>v?new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(v):'—';useSeoMeta({title:'Manage Properties | Lexshield Admin',robots:'noindex,nofollow'})
</script>
